package com.gogleox.scrip.ledger;

import com.gogleox.scrip.account.*;
import com.gogleox.scrip.organization.*;
import com.gogleox.scrip.storage.*;
import java.io.*;
import java.nio.file.Path;
import java.time.Clock;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;

/** Server-owned account and organization state rebuilt solely from the durable journal. */
public final class AccountLedger implements AutoCloseable {
    private static final String INIT="scrip:ledger-init.v1", PLAYER="scrip:player.v1", ACCOUNT="scrip:account.v1";
    private static final String TRANSFER="scrip:transfer.v1", ADJUST="scrip:adjust.v1", CLAIM="scrip:claim.v1", TOMBSTONE="scrip:tombstone.v1";
    private static final String ADMIN_ADJUST="scrip:admin-adjust.v1", FREEZE="scrip:account-freeze.v1";
    private static final String ORG_CREATE="scrip:organization-create.v1", ORG_INVITE="scrip:organization-invite.v1";
    private static final String ORG_ACCEPT="scrip:organization-accept.v1", ORG_REMOVE="scrip:organization-remove.v1", ORG_ROLE="scrip:organization-role.v1";
    private final LedgerStore store; private final Clock clock; private final ExecutorService writer;
    private final Map<AccountId, State> accounts=new HashMap<>();
    private final Map<UUID, AccountId> personal=new HashMap<>();
    private final Map<UUID, KnownPlayer> players=new HashMap<>();
    private final Map<String, UUID> names=new HashMap<>();
    private final Map<UUID, Completed> operations=new HashMap<>();
    private final Set<String> claims=new HashSet<>();
    private final Deque<AdministrativeAuditRecord> administrativeAudit=new ArrayDeque<>();
    private final Map<OrganizationId, OrganizationState> organizations=new HashMap<>();
    private final Map<String, OrganizationId> organizationNames=new HashMap<>();
    private final Map<AccountId, OrganizationId> organizationAccounts=new HashMap<>();
    private final Deque<OrganizationAuditRecord> organizationAudit=new ArrayDeque<>();
    private CurrencyDefinition currency; private boolean closed;

    public static AccountLedger open(Path directory, CurrencyDefinition currency) { return new AccountLedger(JournalFileLedgerStore.open(directory),currency,Clock.systemUTC()); }
    public static AccountLedger open(LedgerStore store, CurrencyDefinition currency) { return new AccountLedger(store,currency,Clock.systemUTC()); }
    AccountLedger(LedgerStore store, CurrencyDefinition requested, Clock clock) {
        this.store=Objects.requireNonNull(store); this.clock=Objects.requireNonNull(clock);
        writer=Executors.newSingleThreadExecutor(r->{Thread thread=new Thread(r,"scrip-account-writer");thread.setDaemon(true);return thread;});
        recover(Objects.requireNonNull(requested));
    }
    private void recover(CurrencyDefinition requested) {
        RecoveryState recovered=store.recover();
        if(recovered.snapshot().isPresent()) throw new StorageException("Account snapshots are not supported before checkpoint integration");
        for(JournalEntry entry:recovered.entries()) replay(entry);
        if(currency==null) { currency=requested; durable(new JournalOperation(UUID.randomUUID(),INIT,encode(out->out.writeUTF(requested.displayName())))); }
        else if(!currency.equals(requested)) throw new StorageException("World currency does not match its durable configuration");
    }

    public CurrencyDefinition currency() { synchronized(this){return currency;} }
    public CompletionStage<AccountSnapshot> registerPlayer(UUID playerId,String verifiedName) { return submit(()->{
        Objects.requireNonNull(playerId,"playerId"); requireName(verifiedName); Instant now=clock.instant(); AccountId id=personal.get(playerId);
        if(id==null){ id=new AccountId(playerId); AccountId created=id; durable(new JournalOperation(UUID.randomUUID(),ACCOUNT,encode(out->{writeId(out,created);writeUuid(out,playerId);writeTime(out,now);}))); applyPersonal(created,playerId,now); }
        KnownPlayer previous=players.get(playerId);
        byte[] playerPayload=encode(out->{writeUuid(out,playerId);out.writeUTF(verifiedName);writeTime(out,now);});
        durable(new JournalOperation(UUID.randomUUID(),PLAYER,playerPayload));
        if(previous!=null) names.remove(key(previous.lastKnownName())); KnownPlayer known=new KnownPlayer(playerId,verifiedName,now); players.put(playerId,known); names.put(key(verifiedName),playerId);
        accounts.get(id).login=now; return snapshot(accounts.get(id));
    }); }
    public Optional<AccountSnapshot> findPersonal(UUID playerId) { synchronized(this){return Optional.ofNullable(personal.get(playerId)).map(accounts::get).map(this::snapshot);} }
    public Optional<AccountSnapshot> findAccount(AccountId id) { synchronized(this){return Optional.ofNullable(accounts.get(id)).map(this::snapshot);} }
    public Optional<KnownPlayer> findKnownPlayer(String name) { synchronized(this){UUID id=names.get(key(name));return Optional.ofNullable(id).map(players::get);} }
    public List<TransactionRecord> history(AccountId id) { synchronized(this){State state=accounts.get(id);return state==null?List.of():List.copyOf(state.history);} }

    public CompletionStage<TransferOutcome> transfer(TransferRequest request) { return submit(()->transferNow(request,false)); }
    private TransferOutcome transferNow(TransferRequest request,boolean organizationAuthorized) {
        Completed prior=operations.get(request.operationId()); if(prior!=null) return prior.matches(request)?TransferOutcome.success(request.operationId(),prior.sequence,true):TransferOutcome.rejected(TransferOutcome.Status.OPERATION_CONFLICT,request.operationId());
        if(request.amount()<=0) return TransferOutcome.rejected(TransferOutcome.Status.INVALID_AMOUNT,request.operationId()); if(request.source().equals(request.destination())) return TransferOutcome.rejected(TransferOutcome.Status.SAME_ACCOUNT,request.operationId());
        State from=accounts.get(request.source()),to=accounts.get(request.destination()); if(from==null||to==null) return TransferOutcome.rejected(TransferOutcome.Status.UNKNOWN_ACCOUNT,request.operationId());
        if((from.type==AccountType.ORGANIZATION||to.type==AccountType.ORGANIZATION)&&!organizationAuthorized) return TransferOutcome.rejected(TransferOutcome.Status.UNAUTHORIZED,request.operationId());
        if(from.lifecycle==AccountLifecycle.TOMBSTONED||to.lifecycle==AccountLifecycle.TOMBSTONED) return TransferOutcome.rejected(TransferOutcome.Status.ACCOUNT_TOMBSTONED,request.operationId());
        if(from.lifecycle==AccountLifecycle.FROZEN) return TransferOutcome.rejected(TransferOutcome.Status.FROZEN_ACCOUNT,request.operationId());
        if(from.balance<request.amount()) return TransferOutcome.rejected(TransferOutcome.Status.INSUFFICIENT_FUNDS,request.operationId());
        try{Math.addExact(to.balance,request.amount());}catch(ArithmeticException exception){return TransferOutcome.rejected(TransferOutcome.Status.DESTINATION_OVERFLOW,request.operationId());}
        Instant now=clock.instant(); CommitReceipt receipt;
        try{receipt=durable(new JournalOperation(request.operationId(),TRANSFER,encode(out->{writeId(out,request.source());writeId(out,request.destination());out.writeLong(request.amount());writeTime(out,now);})));}catch(RuntimeException exception){return TransferOutcome.rejected(TransferOutcome.Status.STORAGE_FAILURE,request.operationId());}
        applyTransfer(request,receipt.sequence(),now); return TransferOutcome.success(request.operationId(),receipt.sequence(),false);
    }
    private void applyTransfer(TransferRequest request,long sequence,Instant at) {
        State from=need(request.source()),to=need(request.destination()); from.balance-=request.amount();to.balance+=request.amount();from.activity=to.activity=at;
        add(from,new TransactionRecord(request.operationId(),at,TransactionDirection.OUTGOING,Optional.of(request.destination()),request.amount(),"transfer")); add(to,new TransactionRecord(request.operationId(),at,TransactionDirection.INCOMING,Optional.of(request.source()),request.amount(),"transfer"));
        operations.put(request.operationId(),new Completed(request,sequence));
    }
    public CompletionStage<TransferOutcome> adjust(AdjustmentRequest request){return submit(()->adjustNow(request));}
    private TransferOutcome adjustNow(AdjustmentRequest request) {
        if(operations.containsKey(request.operationId()))return TransferOutcome.rejected(TransferOutcome.Status.OPERATION_CONFLICT,request.operationId()); State state=accounts.get(request.account());if(state==null)return TransferOutcome.rejected(TransferOutcome.Status.UNKNOWN_ACCOUNT,request.operationId());
        return adjustState(request.operationId(),state,request.delta(),request.reason(),ADJUST,out->{writeId(out,request.account());out.writeLong(request.delta());out.writeUTF(request.reason());writeTime(out,clock.instant());},request);
    }
    public CompletionStage<TransferOutcome> adjustAdministratively(AdminAdjustmentRequest request){return submit(()->{
        if(operations.containsKey(request.operationId()))return TransferOutcome.rejected(TransferOutcome.Status.OPERATION_CONFLICT,request.operationId());State state=accounts.get(request.account());if(state==null)return TransferOutcome.rejected(TransferOutcome.Status.UNKNOWN_ACCOUNT,request.operationId());if(state.lifecycle==AccountLifecycle.TOMBSTONED)return TransferOutcome.rejected(TransferOutcome.Status.ACCOUNT_TOMBSTONED,request.operationId());
        long next;try{next=Math.addExact(state.balance,request.delta());}catch(ArithmeticException exception){return TransferOutcome.rejected(TransferOutcome.Status.DESTINATION_OVERFLOW,request.operationId());}if(next<0)return TransferOutcome.rejected(TransferOutcome.Status.INSUFFICIENT_FUNDS,request.operationId());Instant now=clock.instant();CommitReceipt receipt;
        try{receipt=durable(new JournalOperation(request.operationId(),ADMIN_ADJUST,encode(out->{writeId(out,request.account());out.writeLong(request.delta());out.writeUTF(request.reason());writeActor(out,request.actor());writeTime(out,now);})));}catch(RuntimeException exception){return TransferOutcome.rejected(TransferOutcome.Status.STORAGE_FAILURE,request.operationId());}
        state.balance=next;state.activity=now;add(state,new TransactionRecord(request.operationId(),now,TransactionDirection.ADJUSTMENT,Optional.empty(),Math.abs(request.delta()),request.reason()));AdministrativeAuditRecord audit=new AdministrativeAuditRecord(receipt.sequence(),request.operationId(),request.delta()>0?AdministrativeAction.GRANT:AdministrativeAction.DEDUCT,request.account(),request.actor(),Math.abs(request.delta()),request.reason(),now);addAudit(audit);operations.put(request.operationId(),new Completed(request,receipt.sequence()));return TransferOutcome.success(request.operationId(),receipt.sequence(),false);
    });}
    private TransferOutcome adjustState(UUID operationId,State state,long delta,String reason,String type,Encoder encoder,Object request){
        long next;try{next=Math.addExact(state.balance,delta);}catch(ArithmeticException exception){return TransferOutcome.rejected(TransferOutcome.Status.DESTINATION_OVERFLOW,operationId);}if(next<0)return TransferOutcome.rejected(TransferOutcome.Status.INSUFFICIENT_FUNDS,operationId);Instant now=clock.instant();CommitReceipt receipt;try{receipt=durable(new JournalOperation(operationId,type,encode(encoder)));}catch(RuntimeException exception){return TransferOutcome.rejected(TransferOutcome.Status.STORAGE_FAILURE,operationId);}state.balance=next;state.activity=now;add(state,new TransactionRecord(operationId,now,TransactionDirection.ADJUSTMENT,Optional.empty(),Math.abs(delta),reason));operations.put(operationId,new Completed(request,receipt.sequence()));return TransferOutcome.success(operationId,receipt.sequence(),false);
    }
    public CompletionStage<AccountControlOutcome> setFrozen(UUID operationId,AccountId account,boolean frozen,AuditActor actor,String reason){return submit(()->{
        Objects.requireNonNull(operationId);Objects.requireNonNull(account);Objects.requireNonNull(actor);requireReason(reason);if(operations.containsKey(operationId))return AccountControlOutcome.rejected(AccountControlOutcome.Status.OPERATION_CONFLICT,operationId);State state=accounts.get(account);if(state==null)return AccountControlOutcome.rejected(AccountControlOutcome.Status.UNKNOWN_ACCOUNT,operationId);if(state.lifecycle==AccountLifecycle.TOMBSTONED)return AccountControlOutcome.rejected(AccountControlOutcome.Status.ACCOUNT_TOMBSTONED,operationId);if((state.lifecycle==AccountLifecycle.FROZEN)==frozen)return AccountControlOutcome.rejected(AccountControlOutcome.Status.ALREADY_IN_REQUESTED_STATE,operationId);Instant now=clock.instant();CommitReceipt receipt;
        try{receipt=durable(new JournalOperation(operationId,FREEZE,encode(out->{writeId(out,account);out.writeBoolean(frozen);out.writeUTF(reason);writeActor(out,actor);writeTime(out,now);})));}catch(RuntimeException exception){return AccountControlOutcome.rejected(AccountControlOutcome.Status.STORAGE_FAILURE,operationId);}state.lifecycle=frozen?AccountLifecycle.FROZEN:AccountLifecycle.ACTIVE;AdministrativeAuditRecord audit=new AdministrativeAuditRecord(receipt.sequence(),operationId,frozen?AdministrativeAction.FREEZE:AdministrativeAction.UNFREEZE,account,actor,0,reason,now);addAudit(audit);operations.put(operationId,new Completed(audit,receipt.sequence()));return AccountControlOutcome.success(operationId,audit);
    });}
    public List<AdministrativeAuditRecord> administrativeAudit(){synchronized(this){return List.copyOf(administrativeAudit);}}
    public List<AdministrativeAuditRecord> administrativeAudit(AccountId account){synchronized(this){return administrativeAudit.stream().filter(record->record.account().equals(account)).toList();}}
    public CompletionStage<Boolean> recordPermanentClaim(String claimId){return submit(()->{if(claimId==null||claimId.isBlank()||claimId.length()>256)throw new IllegalArgumentException("Invalid permanent claim identifier");if(claims.contains(claimId))return false;durable(new JournalOperation(UUID.randomUUID(),CLAIM,encode(out->out.writeUTF(claimId))));claims.add(claimId);return true;});}
    public boolean hasPermanentClaim(String claimId){synchronized(this){return claims.contains(claimId);}}

    public CompletionStage<OrganizationOutcome> createOrganization(UUID operationId,String name,UUID ownerId){return submit(()->{
        Objects.requireNonNull(operationId);requireOrganizationName(name);Objects.requireNonNull(ownerId);if(operations.containsKey(operationId))return OrganizationOutcome.rejected(OrganizationOutcome.Status.OPERATION_CONFLICT,operationId);if(!personal.containsKey(ownerId))return OrganizationOutcome.rejected(OrganizationOutcome.Status.UNKNOWN_PLAYER,operationId);if(organizationNames.containsKey(key(name)))return OrganizationOutcome.rejected(OrganizationOutcome.Status.NAME_CONFLICT,operationId);
        OrganizationId id=new OrganizationId(UUID.randomUUID());AccountId account=new AccountId(UUID.randomUUID());Instant now=clock.instant();CommitReceipt receipt;
        try{receipt=durable(new JournalOperation(operationId,ORG_CREATE,encode(out->{writeOrganizationId(out,id);writeId(out,account);out.writeUTF(name);writeUuid(out,ownerId);writeTime(out,now);})));}catch(RuntimeException exception){return OrganizationOutcome.rejected(OrganizationOutcome.Status.STORAGE_FAILURE,operationId);}applyOrganization(id,account,name,ownerId,now);OrganizationState organization=organizations.get(id);OrganizationAuditRecord audit=new OrganizationAuditRecord(receipt.sequence(),operationId,id,OrganizationAuditAction.CREATED,ownerId,Optional.of(ownerId),"created",now);addOrganizationAudit(audit);operations.put(operationId,new Completed(audit,receipt.sequence()));return OrganizationOutcome.success(operationId,organizationSnapshot(organization));
    });}
    public Optional<OrganizationSnapshot> findOrganization(OrganizationId id){synchronized(this){return Optional.ofNullable(organizations.get(id)).map(this::organizationSnapshot);}}
    public Optional<OrganizationSnapshot> findOrganization(String name){synchronized(this){return Optional.ofNullable(organizationNames.get(key(name))).map(organizations::get).map(this::organizationSnapshot);}}
    public Optional<OrganizationRole> organizationRole(OrganizationId id,UUID playerId){synchronized(this){OrganizationState state=organizations.get(id);return state==null?Optional.empty():Optional.ofNullable(state.members.get(playerId));}}
    public List<AccountAccess> accessibleAccounts(UUID playerId){synchronized(this){List<AccountAccess> access=new ArrayList<>();AccountId personalId=personal.get(playerId);if(personalId!=null)access.add(new AccountAccess(personalId,AccountType.PERSONAL,Optional.empty(),Optional.empty()));for(OrganizationState organization:organizations.values()){OrganizationRole role=organization.members.get(playerId);if(role!=null)access.add(new AccountAccess(organization.account,AccountType.ORGANIZATION,Optional.of(organization.id),Optional.of(role)));}return List.copyOf(access);}}
    public List<TransactionRecord> organizationHistory(OrganizationId id,UUID actorId){synchronized(this){OrganizationState organization=organizations.get(id);if(organization==null||!organization.members.containsKey(actorId))return List.of();return List.copyOf(accounts.get(organization.account).history);}}
    public List<OrganizationAuditRecord> organizationAudit(OrganizationId id,UUID actorId){synchronized(this){OrganizationState organization=organizations.get(id);if(organization==null||!organization.members.containsKey(actorId))return List.of();return organizationAudit.stream().filter(record->record.organizationId().equals(id)).toList();}}
    public CompletionStage<OrganizationOutcome> inviteMember(UUID operationId,OrganizationId id,UUID actorId,UUID inviteeId){return submit(()->{
        if(operations.containsKey(operationId))return OrganizationOutcome.rejected(OrganizationOutcome.Status.OPERATION_CONFLICT,operationId);OrganizationState organization=organizations.get(id);if(organization==null)return OrganizationOutcome.rejected(OrganizationOutcome.Status.UNKNOWN_ORGANIZATION,operationId);if(!personal.containsKey(inviteeId))return OrganizationOutcome.rejected(OrganizationOutcome.Status.UNKNOWN_PLAYER,operationId);OrganizationRole actor=organization.members.get(actorId);if(actor==null)return OrganizationOutcome.rejected(OrganizationOutcome.Status.NOT_MEMBER,operationId);if(!actor.canManageMembers())return OrganizationOutcome.rejected(OrganizationOutcome.Status.UNAUTHORIZED,operationId);if(organization.members.containsKey(inviteeId)||organization.invitations.contains(inviteeId))return OrganizationOutcome.rejected(OrganizationOutcome.Status.ALREADY_MEMBER,operationId);Instant now=clock.instant();CommitReceipt receipt;
        try{receipt=durable(new JournalOperation(operationId,ORG_INVITE,encode(out->{writeOrganizationId(out,id);writeUuid(out,actorId);writeUuid(out,inviteeId);writeTime(out,now);})));}catch(RuntimeException exception){return OrganizationOutcome.rejected(OrganizationOutcome.Status.STORAGE_FAILURE,operationId);}organization.invitations.add(inviteeId);OrganizationAuditRecord audit=new OrganizationAuditRecord(receipt.sequence(),operationId,id,OrganizationAuditAction.INVITED,actorId,Optional.of(inviteeId),"member",now);addOrganizationAudit(audit);operations.put(operationId,new Completed(audit,receipt.sequence()));return OrganizationOutcome.success(operationId,organizationSnapshot(organization));
    });}
    public CompletionStage<OrganizationOutcome> acceptInvitation(UUID operationId,OrganizationId id,UUID actorId){return submit(()->{
        if(operations.containsKey(operationId))return OrganizationOutcome.rejected(OrganizationOutcome.Status.OPERATION_CONFLICT,operationId);OrganizationState organization=organizations.get(id);if(organization==null)return OrganizationOutcome.rejected(OrganizationOutcome.Status.UNKNOWN_ORGANIZATION,operationId);if(!personal.containsKey(actorId))return OrganizationOutcome.rejected(OrganizationOutcome.Status.UNKNOWN_PLAYER,operationId);if(organization.members.containsKey(actorId))return OrganizationOutcome.rejected(OrganizationOutcome.Status.ALREADY_MEMBER,operationId);if(!organization.invitations.contains(actorId))return OrganizationOutcome.rejected(OrganizationOutcome.Status.INVITATION_MISSING,operationId);Instant now=clock.instant();CommitReceipt receipt;
        try{receipt=durable(new JournalOperation(operationId,ORG_ACCEPT,encode(out->{writeOrganizationId(out,id);writeUuid(out,actorId);writeTime(out,now);})));}catch(RuntimeException exception){return OrganizationOutcome.rejected(OrganizationOutcome.Status.STORAGE_FAILURE,operationId);}organization.invitations.remove(actorId);organization.members.put(actorId,OrganizationRole.MEMBER);OrganizationAuditRecord audit=new OrganizationAuditRecord(receipt.sequence(),operationId,id,OrganizationAuditAction.INVITATION_ACCEPTED,actorId,Optional.of(actorId),"member",now);addOrganizationAudit(audit);operations.put(operationId,new Completed(audit,receipt.sequence()));return OrganizationOutcome.success(operationId,organizationSnapshot(organization));
    });}
    public CompletionStage<OrganizationOutcome> removeMember(UUID operationId,OrganizationId id,UUID actorId,UUID subjectId){return submit(()->{
        if(operations.containsKey(operationId))return OrganizationOutcome.rejected(OrganizationOutcome.Status.OPERATION_CONFLICT,operationId);OrganizationState organization=organizations.get(id);if(organization==null)return OrganizationOutcome.rejected(OrganizationOutcome.Status.UNKNOWN_ORGANIZATION,operationId);OrganizationRole actor=organization.members.get(actorId),subject=organization.members.get(subjectId);if(actor==null||subject==null)return OrganizationOutcome.rejected(OrganizationOutcome.Status.NOT_MEMBER,operationId);if(subject==OrganizationRole.OWNER)return OrganizationOutcome.rejected(OrganizationOutcome.Status.OWNER_PROTECTED,operationId);if(!actor.canManageMembers()||(actor==OrganizationRole.MANAGER&&subject!=OrganizationRole.MEMBER))return OrganizationOutcome.rejected(OrganizationOutcome.Status.UNAUTHORIZED,operationId);Instant now=clock.instant();CommitReceipt receipt;
        try{receipt=durable(new JournalOperation(operationId,ORG_REMOVE,encode(out->{writeOrganizationId(out,id);writeUuid(out,actorId);writeUuid(out,subjectId);writeTime(out,now);})));}catch(RuntimeException exception){return OrganizationOutcome.rejected(OrganizationOutcome.Status.STORAGE_FAILURE,operationId);}organization.members.remove(subjectId);organization.invitations.remove(subjectId);OrganizationAuditRecord audit=new OrganizationAuditRecord(receipt.sequence(),operationId,id,OrganizationAuditAction.MEMBER_REMOVED,actorId,Optional.of(subjectId),"removed",now);addOrganizationAudit(audit);operations.put(operationId,new Completed(audit,receipt.sequence()));return OrganizationOutcome.success(operationId,organizationSnapshot(organization));
    });}
    public CompletionStage<OrganizationOutcome> changeRole(UUID operationId,OrganizationId id,UUID actorId,UUID subjectId,OrganizationRole role){return submit(()->{
        if(operations.containsKey(operationId))return OrganizationOutcome.rejected(OrganizationOutcome.Status.OPERATION_CONFLICT,operationId);OrganizationState organization=organizations.get(id);if(organization==null)return OrganizationOutcome.rejected(OrganizationOutcome.Status.UNKNOWN_ORGANIZATION,operationId);OrganizationRole actor=organization.members.get(actorId),subject=organization.members.get(subjectId);if(actor==null||subject==null)return OrganizationOutcome.rejected(OrganizationOutcome.Status.NOT_MEMBER,operationId);if(actor!=OrganizationRole.OWNER)return OrganizationOutcome.rejected(OrganizationOutcome.Status.UNAUTHORIZED,operationId);if(subject==OrganizationRole.OWNER)return OrganizationOutcome.rejected(OrganizationOutcome.Status.OWNER_PROTECTED,operationId);if(role==OrganizationRole.OWNER||role==subject)return OrganizationOutcome.rejected(OrganizationOutcome.Status.INVALID_ROLE_CHANGE,operationId);Instant now=clock.instant();CommitReceipt receipt;
        try{receipt=durable(new JournalOperation(operationId,ORG_ROLE,encode(out->{writeOrganizationId(out,id);writeUuid(out,actorId);writeUuid(out,subjectId);out.writeInt(role.ordinal());writeTime(out,now);})));}catch(RuntimeException exception){return OrganizationOutcome.rejected(OrganizationOutcome.Status.STORAGE_FAILURE,operationId);}organization.members.put(subjectId,role);OrganizationAuditRecord audit=new OrganizationAuditRecord(receipt.sequence(),operationId,id,OrganizationAuditAction.ROLE_CHANGED,actorId,Optional.of(subjectId),role.name(),now);addOrganizationAudit(audit);operations.put(operationId,new Completed(audit,receipt.sequence()));return OrganizationOutcome.success(operationId,organizationSnapshot(organization));
    });}
    public OrganizationOutcome requestOwnershipTransfer(UUID operationId,OrganizationId id,UUID actorId,UUID candidateId){synchronized(this){OrganizationState organization=organizations.get(id);if(organization==null)return OrganizationOutcome.rejected(OrganizationOutcome.Status.UNKNOWN_ORGANIZATION,operationId);if(organization.members.get(actorId)!=OrganizationRole.OWNER)return OrganizationOutcome.rejected(OrganizationOutcome.Status.UNAUTHORIZED,operationId);if(organization.members.get(candidateId)==null)return OrganizationOutcome.rejected(OrganizationOutcome.Status.NOT_MEMBER,operationId);return OrganizationOutcome.rejected(OrganizationOutcome.Status.POLICY_UNRESOLVED,operationId);}}
    public CompletionStage<TransferOutcome> depositToOrganization(UUID operationId,OrganizationId id,UUID actorId,long amount){return submit(()->{
        OrganizationState organization=organizations.get(id);if(organization==null)return TransferOutcome.rejected(TransferOutcome.Status.UNKNOWN_ACCOUNT,operationId);if(!organization.members.containsKey(actorId))return TransferOutcome.rejected(TransferOutcome.Status.UNAUTHORIZED,operationId);AccountId source=personal.get(actorId);if(source==null)return TransferOutcome.rejected(TransferOutcome.Status.UNKNOWN_ACCOUNT,operationId);return transferNow(new TransferRequest(operationId,source,organization.account,amount),true);
    });}
    public CompletionStage<TransferOutcome> spendOrganizationFunds(UUID operationId,OrganizationId id,UUID actorId,AccountId destination,long amount){return submit(()->{
        OrganizationState organization=organizations.get(id);if(organization==null)return TransferOutcome.rejected(TransferOutcome.Status.UNKNOWN_ACCOUNT,operationId);OrganizationRole role=organization.members.get(actorId);if(role==null||!role.canSpendFunds())return TransferOutcome.rejected(TransferOutcome.Status.UNAUTHORIZED,operationId);return transferNow(new TransferRequest(operationId,organization.account,destination,amount),true);
    });}

    private CommitReceipt durable(JournalOperation operation){try{return store.commit(operation).toCompletableFuture().join();}catch(CompletionException exception){throw new StorageException("Durable ledger commit failed",exception.getCause());}}
    private <T> CompletionStage<T> submit(Callable<T> task){CompletableFuture<T> result=new CompletableFuture<>();synchronized(this){if(closed){result.completeExceptionally(new StorageException("Account ledger is closed"));return result;}}try{writer.execute(()->{try{result.complete(task.call());}catch(Throwable throwable){result.completeExceptionally(throwable);}});}catch(RuntimeException exception){result.completeExceptionally(exception);}return result;}
    private void replay(JournalEntry entry){try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(entry.operation().payload()))){switch(entry.operation().type()){
        case INIT -> currency=new CurrencyDefinition(in.readUTF());
        case ACCOUNT -> applyPersonal(readId(in),readUuid(in),readTime(in));
        case PLAYER -> replayPlayer(readUuid(in),in.readUTF(),readTime(in));
        case TRANSFER -> replayTransfer(entry.sequence(),entry.operation().operationId(),readId(in),readId(in),in.readLong(),readTime(in));
        case ADJUST -> replayAdjust(entry.sequence(),entry.operation().operationId(),readId(in),in.readLong(),in.readUTF(),readTime(in));
        case ADMIN_ADJUST -> replayAdministrativeAdjust(entry.sequence(),entry.operation().operationId(),readId(in),in.readLong(),in.readUTF(),readActor(in),readTime(in));
        case FREEZE -> replayFreeze(entry.sequence(),entry.operation().operationId(),readId(in),in.readBoolean(),in.readUTF(),readActor(in),readTime(in));
        case ORG_CREATE -> replayOrganizationCreate(entry.sequence(),entry.operation().operationId(),readOrganizationId(in),readId(in),in.readUTF(),readUuid(in),readTime(in));
        case ORG_INVITE -> replayInvitation(entry.sequence(),entry.operation().operationId(),readOrganizationId(in),readUuid(in),readUuid(in),readTime(in));
        case ORG_ACCEPT -> replayAccept(entry.sequence(),entry.operation().operationId(),readOrganizationId(in),readUuid(in),readTime(in));
        case ORG_REMOVE -> replayRemove(entry.sequence(),entry.operation().operationId(),readOrganizationId(in),readUuid(in),readUuid(in),readTime(in));
        case ORG_ROLE -> replayRole(entry.sequence(),entry.operation().operationId(),readOrganizationId(in),readUuid(in),readUuid(in),readRole(in),readTime(in));
        case CLAIM -> claims.add(in.readUTF());
        case TOMBSTONE -> {State state=need(readId(in));state.lifecycle=AccountLifecycle.TOMBSTONED;}
        default -> throw new StorageException("Unknown account journal operation");
    }if(in.available()!=0)throw new StorageException("Account journal operation has trailing bytes");}catch(IOException|IllegalArgumentException exception){throw new StorageException("Cannot replay account journal operation",exception);}}
    private void replayPlayer(UUID id,String name,Instant at){requireName(name);KnownPlayer previous=players.put(id,new KnownPlayer(id,name,at));if(previous!=null)names.remove(key(previous.lastKnownName()));names.put(key(name),id);AccountId account=personal.get(id);if(account!=null)need(account).login=at;}
    private void replayTransfer(long sequence,UUID operationId,AccountId source,AccountId destination,long amount,Instant at){if(amount<=0||operations.containsKey(operationId))throw new StorageException("Invalid transfer replay");State from=need(source),to=need(destination);if(from.lifecycle!=AccountLifecycle.ACTIVE||to.lifecycle==AccountLifecycle.TOMBSTONED||from.balance<amount)throw new StorageException("Transfer replay violates account state");try{Math.addExact(to.balance,amount);}catch(ArithmeticException exception){throw new StorageException("Transfer replay overflows account",exception);}applyTransfer(new TransferRequest(operationId,source,destination,amount),sequence,at);}
    private void replayAdjust(long sequence,UUID operationId,AccountId id,long delta,String reason,Instant at){State state=need(id);long next;try{next=Math.addExact(state.balance,delta);}catch(ArithmeticException exception){throw new StorageException("Adjustment replay overflows account",exception);}if(next<0||operations.containsKey(operationId))throw new StorageException("Invalid adjustment replay");state.balance=next;state.activity=at;add(state,new TransactionRecord(operationId,at,TransactionDirection.ADJUSTMENT,Optional.empty(),Math.abs(delta),reason));operations.put(operationId,new Completed(new AdjustmentRequest(operationId,id,delta,reason),sequence));}
    private void replayAdministrativeAdjust(long sequence,UUID operationId,AccountId id,long delta,String reason,AuditActor actor,Instant at){State state=need(id);long next;try{next=Math.addExact(state.balance,delta);}catch(ArithmeticException exception){throw new StorageException("Administrative adjustment replay overflows account",exception);}if(delta==0||next<0||operations.containsKey(operationId)||state.lifecycle==AccountLifecycle.TOMBSTONED)throw new StorageException("Invalid administrative adjustment replay");state.balance=next;state.activity=at;add(state,new TransactionRecord(operationId,at,TransactionDirection.ADJUSTMENT,Optional.empty(),Math.abs(delta),reason));AdministrativeAuditRecord audit=new AdministrativeAuditRecord(sequence,operationId,delta>0?AdministrativeAction.GRANT:AdministrativeAction.DEDUCT,id,actor,Math.abs(delta),reason,at);addAudit(audit);operations.put(operationId,new Completed(audit,sequence));}
    private void replayFreeze(long sequence,UUID operationId,AccountId id,boolean frozen,String reason,AuditActor actor,Instant at){State state=need(id);if(state.lifecycle==AccountLifecycle.TOMBSTONED||operations.containsKey(operationId)||(state.lifecycle==AccountLifecycle.FROZEN)==frozen)throw new StorageException("Invalid freeze replay");state.lifecycle=frozen?AccountLifecycle.FROZEN:AccountLifecycle.ACTIVE;AdministrativeAuditRecord audit=new AdministrativeAuditRecord(sequence,operationId,frozen?AdministrativeAction.FREEZE:AdministrativeAction.UNFREEZE,id,actor,0,reason,at);addAudit(audit);operations.put(operationId,new Completed(audit,sequence));}
    private void replayOrganizationCreate(long sequence,UUID operationId,OrganizationId id,AccountId account,String name,UUID owner,Instant at){if(operations.containsKey(operationId)||organizations.containsKey(id)||organizationNames.containsKey(key(name))||!personal.containsKey(owner))throw new StorageException("Invalid organization create replay");applyOrganization(id,account,name,owner,at);OrganizationAuditRecord audit=new OrganizationAuditRecord(sequence,operationId,id,OrganizationAuditAction.CREATED,owner,Optional.of(owner),"created",at);addOrganizationAudit(audit);operations.put(operationId,new Completed(audit,sequence));}
    private void replayInvitation(long sequence,UUID operationId,OrganizationId id,UUID actor,UUID target,Instant at){OrganizationState organization=needOrganization(id);if(operations.containsKey(operationId)||!personal.containsKey(target)||!organization.members.getOrDefault(actor,OrganizationRole.MEMBER).canManageMembers()||organization.members.containsKey(target)||!organization.invitations.add(target))throw new StorageException("Invalid organization invitation replay");OrganizationAuditRecord audit=new OrganizationAuditRecord(sequence,operationId,id,OrganizationAuditAction.INVITED,actor,Optional.of(target),"member",at);addOrganizationAudit(audit);operations.put(operationId,new Completed(audit,sequence));}
    private void replayAccept(long sequence,UUID operationId,OrganizationId id,UUID actor,Instant at){OrganizationState organization=needOrganization(id);if(operations.containsKey(operationId)||organization.members.containsKey(actor)||!organization.invitations.remove(actor))throw new StorageException("Invalid organization acceptance replay");organization.members.put(actor,OrganizationRole.MEMBER);OrganizationAuditRecord audit=new OrganizationAuditRecord(sequence,operationId,id,OrganizationAuditAction.INVITATION_ACCEPTED,actor,Optional.of(actor),"member",at);addOrganizationAudit(audit);operations.put(operationId,new Completed(audit,sequence));}
    private void replayRemove(long sequence,UUID operationId,OrganizationId id,UUID actor,UUID target,Instant at){OrganizationState organization=needOrganization(id);OrganizationRole actorRole=organization.members.get(actor),targetRole=organization.members.get(target);if(operations.containsKey(operationId)||actorRole==null||targetRole==null||targetRole==OrganizationRole.OWNER||!actorRole.canManageMembers()||(actorRole==OrganizationRole.MANAGER&&targetRole!=OrganizationRole.MEMBER))throw new StorageException("Invalid organization removal replay");organization.members.remove(target);organization.invitations.remove(target);OrganizationAuditRecord audit=new OrganizationAuditRecord(sequence,operationId,id,OrganizationAuditAction.MEMBER_REMOVED,actor,Optional.of(target),"removed",at);addOrganizationAudit(audit);operations.put(operationId,new Completed(audit,sequence));}
    private void replayRole(long sequence,UUID operationId,OrganizationId id,UUID actor,UUID target,OrganizationRole role,Instant at){OrganizationState organization=needOrganization(id);OrganizationRole targetRole=organization.members.get(target);if(operations.containsKey(operationId)||organization.members.get(actor)!=OrganizationRole.OWNER||targetRole==null||targetRole==OrganizationRole.OWNER||role==OrganizationRole.OWNER||role==targetRole)throw new StorageException("Invalid organization role replay");organization.members.put(target,role);OrganizationAuditRecord audit=new OrganizationAuditRecord(sequence,operationId,id,OrganizationAuditAction.ROLE_CHANGED,actor,Optional.of(target),role.name(),at);addOrganizationAudit(audit);operations.put(operationId,new Completed(audit,sequence));}
    private void applyPersonal(AccountId id,UUID owner,Instant at){if(accounts.containsKey(id)||personal.containsKey(owner))throw new StorageException("Duplicate personal account");accounts.put(id,new State(id,AccountType.PERSONAL,owner,at));personal.put(owner,id);}
    private void applyOrganization(OrganizationId id,AccountId account,String name,UUID owner,Instant at){if(accounts.containsKey(account)||organizations.containsKey(id)||organizationNames.containsKey(key(name))||organizationAccounts.containsKey(account))throw new StorageException("Duplicate organization");requireOrganizationName(name);State accountState=new State(account,AccountType.ORGANIZATION,null,at);accounts.put(account,accountState);OrganizationState organization=new OrganizationState(id,account,name,owner,at);organizations.put(id,organization);organizationNames.put(key(name),id);organizationAccounts.put(account,id);}
    private State need(AccountId id){State state=accounts.get(id);if(state==null)throw new StorageException("Journal references unknown account");return state;}
    private OrganizationState needOrganization(OrganizationId id){OrganizationState organization=organizations.get(id);if(organization==null)throw new StorageException("Journal references unknown organization");return organization;}
    private AccountSnapshot snapshot(State state){return new AccountSnapshot(state.id,state.owner,state.type,new Balance(state.balance),state.created,state.login,state.activity,state.lifecycle);}
    private OrganizationSnapshot organizationSnapshot(OrganizationState state){return new OrganizationSnapshot(state.id,state.name,state.account,state.owner,state.members.size(),state.created);}
    private static void add(State state,TransactionRecord record){state.history.addFirst(record);while(state.history.size()>100)state.history.removeLast();}
    private void addAudit(AdministrativeAuditRecord record){administrativeAudit.addFirst(record);while(administrativeAudit.size()>1000)administrativeAudit.removeLast();}
    private void addOrganizationAudit(OrganizationAuditRecord record){organizationAudit.addFirst(record);while(organizationAudit.size()>1000)organizationAudit.removeLast();}
    private static String key(String name){return name.toLowerCase(Locale.ROOT);}
    private static void requireName(String value){if(value==null||value.isBlank()||value.length()>16)throw new IllegalArgumentException("Invalid verified player name");}
    private static void requireOrganizationName(String value){if(value==null||value.isBlank()||value.length()>32||!value.matches("[A-Za-z0-9 _.-]+"))throw new IllegalArgumentException("Invalid organization name");}
    private static void requireReason(String value){if(value==null||value.isBlank()||value.length()>128)throw new IllegalArgumentException("Reason must be bounded");}
    private static byte[] encode(Encoder encoder){try{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){encoder.write(out);}return bytes.toByteArray();}catch(IOException exception){throw new IllegalStateException(exception);}}
    private static void writeUuid(DataOutputStream out,UUID id)throws IOException{out.writeLong(id.getMostSignificantBits());out.writeLong(id.getLeastSignificantBits());}
    private static UUID readUuid(DataInputStream in)throws IOException{return new UUID(in.readLong(),in.readLong());}
    private static void writeId(DataOutputStream out,AccountId id)throws IOException{writeUuid(out,id.value());}
    private static AccountId readId(DataInputStream in)throws IOException{return new AccountId(readUuid(in));}
    private static void writeOrganizationId(DataOutputStream out,OrganizationId id)throws IOException{writeUuid(out,id.value());}
    private static OrganizationId readOrganizationId(DataInputStream in)throws IOException{return new OrganizationId(readUuid(in));}
    private static void writeActor(DataOutputStream out,AuditActor actor)throws IOException{out.writeBoolean(actor.playerId().isPresent());if(actor.playerId().isPresent())writeUuid(out,actor.playerId().orElseThrow());out.writeUTF(actor.displayName());}
    private static AuditActor readActor(DataInputStream in)throws IOException{Optional<UUID> id=in.readBoolean()?Optional.of(readUuid(in)):Optional.empty();return new AuditActor(id,in.readUTF());}
    private static OrganizationRole readRole(DataInputStream in)throws IOException{int ordinal=in.readInt();OrganizationRole[] roles=OrganizationRole.values();if(ordinal<0||ordinal>=roles.length)throw new StorageException("Invalid organization role");return roles[ordinal];}
    private static void writeTime(DataOutputStream out,Instant instant)throws IOException{out.writeLong(instant.toEpochMilli());}
    private static Instant readTime(DataInputStream in)throws IOException{return Instant.ofEpochMilli(in.readLong());}
    @Override public void close(){synchronized(this){if(closed)return;closed=true;}writer.shutdown();try{if(!writer.awaitTermination(10,TimeUnit.SECONDS))throw new StorageException("Account writer did not stop cleanly");}catch(InterruptedException exception){Thread.currentThread().interrupt();throw new StorageException("Interrupted while closing account writer",exception);}store.close();}
    private interface Encoder { void write(DataOutputStream out)throws IOException; }
    private static final class State { final AccountId id;final AccountType type;final UUID owner;final Instant created;Instant login,activity;long balance;AccountLifecycle lifecycle=AccountLifecycle.ACTIVE;final Deque<TransactionRecord> history=new ArrayDeque<>();State(AccountId id,AccountType type,UUID owner,Instant at){this.id=id;this.type=type;this.owner=owner;created=login=activity=at;} }
    private static final class OrganizationState { final OrganizationId id;final AccountId account;final String name;final UUID owner;final Instant created;final Map<UUID,OrganizationRole> members=new HashMap<>();final Set<UUID> invitations=new HashSet<>();OrganizationState(OrganizationId id,AccountId account,String name,UUID owner,Instant created){this.id=id;this.account=account;this.name=name;this.owner=owner;this.created=created;members.put(owner,OrganizationRole.OWNER);} }
    private record Completed(Object request,long sequence){boolean matches(TransferRequest request){return this.request.equals(request);}}
}
